-- LemmaYard problem catalog for Supabase, part 3 of 6 (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- The same catalog in one file is docs/supabase/problems.sql; the parts exist for SQL
-- editors that refuse a large paste. Run all 6 parts, in any order, after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). Each part is its own transaction
-- over 7 problems, 9 tags and 800 test cases (catalog: 50 problems,
-- 6625 test cases). It writes the same rows as `pnpm problems:import`: upsert by
-- slug (published), tags, and a full replacement of each problem's tags and test cases.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (37, 46, 34, 17, 15, 20, 22)
    AND "slug" NOT IN ($ly$knight-through-walls$ly$, $ly$ladder-word-routes$ly$, $ly$largest-island-coastline$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$lucky-digit-sums$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$knight-through-walls$ly$, $ly$ladder-word-routes$ly$, $ly$largest-island-coastline$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$lucky-digit-sums$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$matrix$ly$, $ly$Matrix$ly$),
  ($ly$graph$ly$, $ly$Graph$ly$),
  ($ly$breadth-first-search$ly$, $ly$Breadth First Search$ly$),
  ($ly$string$ly$, $ly$String$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$sliding-window$ly$, $ly$Sliding Window$ly$),
  ($ly$hash-table$ly$, $ly$Hash Table$ly$),
  ($ly$stack$ly$, $ly$Stack$ly$),
  ($ly$math$ly$, $ly$Math$ly$)
ON CONFLICT ("slug") DO NOTHING;

-- ---- knight-through-walls ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating", "languages", "wide_ints")
VALUES (37, $ly$knight-through-walls$ly$, $ly$Knight Through Walls$ly$, $ly$medium$ly$, $ly$A puzzle board is given as `board`, a list of equally long strings. Each
character is one square:

- `'.'` an open square,
- `'#'` a wall,
- `'S'` the square where a knight stands (open),
- `'T'` the target square (open).

The knight moves like a chess knight: two squares in one direction along a
row or column and then one square sideways, so from row `r`, column `c` it can
reach `(r ± 1, c ± 2)` and `(r ± 2, c ± 1)`. It jumps, so walls on the way do
not stop it, but it can never land on a wall or leave the board.

Return the smallest number of moves that takes the knight from `'S'` to
`'T'`, or `-1` if it cannot get there.

## Constraints

- `1 <= board.length <= 150`
- `1 <= board[i].length <= 150`, and all rows have the same length
- `board` contains exactly one `'S'` and exactly one `'T'`; every other
  character is `'.'` or `'#'`
$ly$, $ly${"name":"knightMoves","params":[{"name":"board","type":"string[]"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1640, $ly${"python","javascript"}$ly$, $ly${}$ly$)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "languages" = EXCLUDED."languages",
  "wide_ints" = EXCLUDED."wide_ints",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$knight-through-walls$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$knight-through-walls$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$matrix$ly$, $ly$graph$ly$, $ly$breadth-first-search$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$knight-through-walls$ly$);
