  (1, $ly${"s":"())(())"}$ly$::jsonb, $ly$4$ly$::jsonb, TRUE),
  (2, $ly${"s":""}$ly$::jsonb, $ly$0$ly$::jsonb, TRUE),
  (3, $ly${"s":"("}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (4, $ly${"s":")"}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (5, $ly${"s":")("}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (6, $ly${"s":"(((("}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (7, $ly${"s":"()(())"}$ly$::jsonb, $ly$6$ly$::jsonb, FALSE),
